/* @lc app=leetcode id=1977 lang=kotlin */ class Solution { fun numberOfCombinations(num: String): Int = if (num[0] == '0') 0 else num.length.let { n -> Array(n + 1) { IntArray(n + 1) }.apply { (n - 1 downTo 0).forEach { i -> (n - 1 downTo 0).forEach { j -> if (num[i] == num[j]) this[i][j] = 1 + this[i + 1][j + 1] } } }.let { lcp -> Array(n) { IntArray(n + 1) }.apply { (0 until n).forEach { i -> (1..n).forEach { len -> this[i][len] = if (len > i + 1) this[i][i + 1] else this[i][len - 1].let { prev -> (i - len + 1).let { start -> if (num[start] == '0') prev else if (start == 0) (prev + 1) % 1000000007 else (prev + this[start - 1][if (start >= len) lcp[start - len][start].let { k -> if (k >= len || num[start - len + k] < num[start + k]) len else len - 1 } else start]) % 1000000007 } } } } }[n - 1][n] } } }